using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.UIElements;
using EternalSteam;
using EternalSteam.OpenWorld;
public static class VerifySingleMapSave {
 static void Check(bool b,string m){if(!b)throw new Exception(m);}
 public static string Main(){
 var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();s.Persistence.Automatic=false;s.Clock.Paused=true;
 Check(!s.Persistence.Blocked,s.Persistence.Status);
 var main=s.Content.MainBase;var area=main.Module<IBuildArea>();
 BuildingInstance Install(BuildingDefinition d){for(int z=-50;z<60;z++)for(int x=-50;x<60;x++){var c=new Vector2Int(x,z);if(!area.Contains(s.Content.GroundWorld.Grid.Center(c,d.Footprint),(Vector2)d.Footprint,WorldGridGeometry.Rotation))continue;if(!s.Content.GroundPlacement.Add(d,c,out _).Success)continue;var result=s.Content.GroundPlacement.Confirm();Check(result.Success,result.Message);return s.Content.GroundWorld.Buildings.Last();}throw new Exception("No position");}
 if(s.Content.GroundWorld.Buildings.Count==1){Install(s.ContentCatalog.Buildings.Single(d=>d.Id=="resource.power_generator"));Install(s.ContentCatalog.Buildings.First(d=>d.Modules.Any(m=>m is ProductionModuleDefinition)&&d.Placement.RequiredNexusLevel==1));Install(s.ContentCatalog.Buildings.First(d=>d.Modules.Any(m=>m is WeaponModuleDefinition)&&d.Placement.RequiredNexusLevel==1));}
 s.Clock.Paused=false;s.AdvanceSimulation(.37f);s.Clock.Paused=true;
 Check(s.Persistence.Save(),s.Persistence.Status);var before=s.Persistence.Capture();File.WriteAllText("/tmp/eternal-save-before.json",JsonUtility.ToJson(before));
 var bad=JsonUtility.FromJson<SingleMapSnapshot>(JsonUtility.ToJson(before));bad.buildings.Add(bad.buildings[0]);bool rejected=false;try{s.Persistence.Validate(bad);}catch{rejected=true;}Check(rejected,"Duplicate ID rejected");
 var input=s.GetComponent<OpenWorldInput>();input.BeginEditing();Check(!s.Persistence.CanSave(out _),"Edit gate");input.Cancel();s.Clock.SetPhase(DayPhase.Night);Check(!s.Persistence.CanSave(out _),"Night gate");s.Clock.SetPhase(DayPhase.Day);
 var dir="/tmp/eternal-store-unit-"+Guid.NewGuid().ToString("N");var store=new JsonSaveStore(dir);var run=Guid.NewGuid().ToString("N");store.Write(run,"first");store.Write(run,"second");Check(store.Read().Payload=="second","Current");File.WriteAllText(store.CurrentPath,"corrupt");Check(store.Read().Recovered&&store.Read().Payload=="first","Backup");store.MarkFailed(run);Check(store.Read().Blocked,"Failed backup denied");store.Archive();Check(store.Read().Payload==null&&!store.Read().Blocked,"New slot");
 return "PASS capture/save, duplicate rejection, editing/night gates, file backup corruption recovery, death backup denial, archived fresh slot. Reload next.";
 }
 public static string Reloaded(){var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();Check(!s.Persistence.Blocked,s.Persistence.Status);Check(s.Clock.Paused,"Load paused");var before=JsonUtility.FromJson<SingleMapSnapshot>(File.ReadAllText("/tmp/eternal-save-before.json"));var after=s.Persistence.Capture();before.savedUtc=after.savedUtc;Check(JsonUtility.ToJson(before)==JsonUtility.ToJson(after),"Snapshot roundtrip mismatch\n"+JsonUtility.ToJson(after));return "PASS actual scene reload: exact snapshot, main model reused, paused.";}

 public static string Expanded(){
 var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();s.Persistence.Automatic=false;s.Clock.Paused=true;Check(!s.Persistence.Blocked,s.Persistence.Status);
 var main=s.Content.MainBase;Check(s.Persistence.Upgrades.TryUpgrade(main,out var why),why);
 bool placed=false;for(int z=-40;z<40&&!placed;z++)for(int x=-40;x<40&&!placed;x++)placed=s.Foundations.AddFoundation(WorldGridGeometry.ToWorld(new Vector3(x*8+4,0,z*8+4)),out _);Check(placed,"Foundation position");var p=s.Foundations.Platforms.Last();
 for(int i=0;i<4;i++){var kind=(EternalSteam.Demo.HordeTowerKind)i;var def=s.Foundations.Definition(kind);var result=p.Placement.Add(def,new Vector2Int(i,0),out var req);Check(result.Success,result.Message);var pos=p.World.Grid.Center(req.Cell,def.Footprint);var view=s.Foundations.CreateTowerPreview(kind,pos,Vector3.forward);view.SetActive(false);p.Factory.ConfigureRequest(req.Id,22,kind);p.Factory.ConfigureExistingRequest(req.Id,view.GetComponent<SceneTower>().RuntimeView());result=p.Placement.Confirm();Check(result.Success,result.Message);p.Factory.ForgetRequest(req.Id);var tower=s.Towers.Last();tower.cooldown=.29f+i*.1f;tower.shot=4+i;Check(s.Persistence.Upgrades.TryUpgrade(tower.building,out why),why);tower.building.Module<HealthModule>().ApplyDamage(17);}
 main.Module<HealthModule>().ApplyDamage(7);
 var bank=new ResourceBank();bank.AddCapacity("a",100);bank.AddCapacity("b",100);bank.Exchange(null,0,"a",10);bank.Exchange(null,0,"b",1);int commits=0;var costs=new[]{new ResourceCost{ResourceId="a",Amount=3},new ResourceCost{ResourceId="b",Amount=2}};Check(!bank.TryPurchase(costs,()=>{commits++;return true;},out _)&&commits==0&&bank.Amount("a")==10,"Insufficient atomic purchase");bank.Exchange(null,0,"b",9);Check(bank.TryPurchase(costs,()=>{commits++;return true;},out _)&&commits==1&&bank.Amount("a")==7&&bank.Amount("b")==8,"One purchase");Check(!bank.TryPurchase(null,()=>true,out _),"Unset differs from free");
 Check(s.Persistence.Save(),s.Persistence.Status);File.WriteAllText("/tmp/eternal-save-before.json",JsonUtility.ToJson(s.Persistence.Capture()));return "PASS foundation + all four legacy upgraded damaged towers, damaged main, atomic costs; saved reload fixture.";
 }
 public static string Defeat(){var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();var id=s.Persistence.RunId;s.Content.MainBase.Module<HealthModule>().ApplyDamage(float.MaxValue);Check(s.Content.Defeated,"Defeated");Check(new JsonSaveStore(Environment.GetEnvironmentVariable("ETERNAL_STEAM_SAVE_TEST_ROOT")).IsFailed(id),"Immediate durable death");Check(!s.Persistence.HasContinue&&!s.Persistence.Save(),"Failed run save/load blocked");UnityEditor.SceneManagement.EditorSceneManager.LoadSceneInPlayMode(s.gameObject.scene.path,new UnityEngine.SceneManagement.LoadSceneParameters(UnityEngine.SceneManagement.LoadSceneMode.Single));return "PASS immediate death marker; restarting scene.";}
 public static string FailedReload(){var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();Check(s.Persistence.Blocked&&s.Content.MainBase==null,"Failed run denied on restart");s.Persistence.NewGame();return "PASS failed restart blocked, requested new game.";}
 public static string Fresh(){var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();s.Clock.Paused=true;Check(!s.Persistence.Blocked&&s.Content.GroundWorld.Buildings.Count==1&&s.Foundations.Platforms.Count==0&&s.Campaign.MainLevel==1,"Clean new game");return "PASS fresh main only, level 1, no old foundations.";}

 public static string Gates(){var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();s.Persistence.Automatic=false;
 var snapshot=s.Persistence.Capture();var count=s.Content.Bases.Buildings.Count;
 void Invalid(Action<SingleMapSnapshot> mutate){var d=JsonUtility.FromJson<SingleMapSnapshot>(JsonUtility.ToJson(snapshot));mutate(d);bool rejected=false;try{s.Persistence.Validate(d);}catch{rejected=true;}Check(rejected&&s.Content.Bases.Buildings.Count==count,"Prevalidation must reject without mutation");}
 Invalid(d=>d.buildings[1].definition="missing");Invalid(d=>d.buildings[1].owner=Guid.NewGuid().ToString("N"));Invalid(d=>d.buildings[1].supply=Guid.NewGuid().ToString("N"));Invalid(d=>d.buildings[1].cell=d.buildings[0].cell);
 var path="/tmp/eternal-save-version-"+Guid.NewGuid().ToString("N");var store=new JsonSaveStore(path);var id=Guid.NewGuid().ToString("N");store.Write(id,"a");store.Write(id,"b");var original=File.ReadAllText(store.CurrentPath).Replace("\"version\": 1","\"version\": 999");File.WriteAllText(store.CurrentPath,original);Check(store.Read().Blocked&&!store.Read().Recovered&&File.ReadAllText(store.CurrentPath)==original,"Unsupported version preserved, no fallback");
 Check(s.Spawn("1"),"Spawn");Check(!s.Persistence.CanSave(out var why)&&why.Contains("전투"),"Alive enemy rejects paused save");s.Enemies.Reset();s.SpawnStream.Request(1,false);Check(!s.Persistence.CanSave(out why)&&why.Contains("소환"),"Pending dev spawn gate");
 s.Persistence.ContinueSaved();return "PASS missing content, overlap, invalid power reference, unsupported version, paused enemy and dev queue gates.";}

 public static string OrbSave(){var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();s.Persistence.Automatic=false;s.Clock.Paused=true;Check(s.Assault.Energy.PerfectOrb,"Run VerifyStartLoop first");s.Enemies.Reset();s.Clock.SetPhase(DayPhase.Day);Check(s.Persistence.Save(),s.Persistence.Status);File.WriteAllText("/tmp/eternal-save-before.json",JsonUtility.ToJson(s.Persistence.Capture()));s.Persistence.ContinueSaved();return "Saved cleared orb, budget and RNG; reload requested.";}
 public static string Transients(){var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();s.Clock.Paused=true;var weapon=s.Content.Bases.Buildings.SelectMany(b=>b.Modules).OfType<WeaponRuntime>().First();foreach(var name in new[]{"flights","chains"}){var field=typeof(WeaponRuntime).GetField(name,System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);var list=(System.Collections.IList)field.GetValue(weapon);var item=Activator.CreateInstance(field.FieldType.GetGenericArguments()[0]);list.Add(item);Check(!s.Persistence.CanSave(out var why)&&why.Contains("투사체"),name+" save gate");list.Clear();}return "PASS projectile and chain in-flight gates.";}
 public static string Ui(){var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();var hud=UnityEngine.Object.FindFirstObjectByType<OpenWorldHud>();var root=hud.GetComponent<UnityEngine.UIElements.UIDocument>().rootVisualElement;hud.Refresh();Check(root.Q<UnityEngine.UIElements.Button>("save")!=null&&root.Q<UnityEngine.UIElements.Button>("load")!=null&&root.Q<UnityEngine.UIElements.Button>("new-game")!=null,"Authored controls");Check(root.Q<UnityEngine.UIElements.Button>("upgrade").text.Contains("무료"),"Free verification label");return "PASS authored save controls and explicit free label.";}

 sealed class BrokenStore:ISaveStore {public SaveRead Read()=>new SaveRead();public void Write(string id,string payload)=>throw new IOException("injected write failure");public void MarkFailed(string id)=>throw new IOException("injected death failure");public bool IsFailed(string id)=>false;public void Archive(){} }
 sealed class Price:IUpgradeCostPolicy {public bool TryQuote(string id,int level,out System.Collections.Generic.List<ResourceCost> costs,out string why){costs=new(){new ResourceCost{ResourceId="test",Amount=10}};why=null;return true;}}
 public static string FailuresAndCosts(){var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();s.Clock.Paused=true;var broken=new SingleMapPersistence(s,new BrokenStore());Check(!broken.Save()&&broken.LastSavedUtc==null&&broken.Status.Contains("실패"),"Write failure not success");
 var b=s.Content.MainBase;int level=b.Module<IUpgradeControl>().Level;var bank=new ResourceBank();bank.AddCapacity("test",100);bank.Exchange(null,0,"test",5);var purchase=new UpgradePurchase(bank,new Price());Check(!purchase.TryUpgrade(b,out _)&&bank.Amount("test")==5&&b.Module<IUpgradeControl>().Level==level,"Insufficient funds no upgrade");bank.Exchange(null,0,"test",15);Check(purchase.TryUpgrade(b,out _)&&bank.Amount("test")==10&&b.Module<IUpgradeControl>().Level==level+1,"Exactly one debit and level");var table=ScriptableObject.CreateInstance<UpgradeCostTable>();Check(!new UpgradePurchase(bank,table).TryUpgrade(b,out _)&&bank.Amount("test")==10,"Missing policy entry not free");UnityEngine.Object.Destroy(table);s.Persistence.ContinueSaved();return "PASS injected write failure reporting and actual upgrade command atomic costs/missing policy.";}

 sealed class CountingStore:ISaveStore {public int Writes;public SaveRead Read()=>new SaveRead();public void Write(string id,string payload){Writes++;}public void MarkFailed(string id){}public bool IsFailed(string id)=>false;public void Archive(){} }
 public static string Autosave(){var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();s.Clock.Paused=true;s.Clock.SetPhase(DayPhase.Day);s.Enemies.Reset();var store=new CountingStore();var service=new SingleMapPersistence(s,store);Check(service.Save(),service.Status);service.Changed();service.Tick(29);Check(store.Writes==1,"Not before 30s");service.Tick(1);Check(store.Writes==2,"Dirty safe 30s");service.Tick(31);Check(store.Writes==2,"Clean skipped");var input=s.GetComponent<OpenWorldInput>();input.BeginEditing();service.RequestAutoSave();Check(store.Writes==2,"Edit pending defers");input.Cancel();service.RequestAutoSave();Check(store.Writes==3,"Safe confirmation save");return "PASS dirty 30-second automatic save, clean skip, unsafe deferral and safe command save.";}
}
